use super::*;use near_sdk::{testing_env,test_utils::VMContextBuilder,PromiseResult};use std::panic::{catch_unwind,AssertUnwindSafe};
fn a(s:&str)->AccountId{s.parse().unwrap()}fn ctx(who:&str,deposit:u128,results:Vec<PromiseResult>){let usage=env::storage_usage();let mut b=VMContextBuilder::new();b.current_account_id(a("token-market.testnet")).predecessor_account_id(a(who)).signer_account_id(a(who)).attached_deposit(NearToken::from_yoctonear(deposit)).account_balance(NearToken::from_near(1000)).storage_usage(usage).prepaid_gas(Gas::from_tgas(300));testing_env!(b.build(),near_sdk::test_vm_config(),near_sdk::RuntimeFeesConfig::test(),Default::default(),results);}
fn feature()->FeatureId{FeatureId{owner:a("merchant.testnet"),product:"app".into(),feature:"safeshare".into(),version:1}}
fn fresh()->TokenMarket{env::set_blockchain_interface(near_sdk::MockedBlockchain::default());ctx("operator.testnet",0,vec![]);TokenMarket::new(a("market.testnet"),a("test-usd.testnet"),6,"TestEPUSD".into())}
fn setup()->TokenMarket{let mut c=fresh();ctx("merchant.testnet",10u128.pow(24),vec![]);c.import_release(feature(),a("dev.testnet"),"a".repeat(64),"b".repeat(64),U128(7000),2500,U128(3000));let proof=near_sdk::serde_json::json!({"id":feature(),"developer":"dev.testnet","terms_hash":"a".repeat(64),"accepted_hash":"a".repeat(64),"approved_sha256":"b".repeat(64),"submitted_sha256":"b".repeat(64),"status":"live"});ctx("token-market.testnet",0,vec![PromiseResult::Successful(near_sdk::serde_json::to_vec(&proof).unwrap())]);assert!(c.on_import(feature()));let hash=c.get_sku(feature()).unwrap().terms_hash;ctx("dev.testnet",0,vec![]);c.accept_token_terms(feature(),hash);c}
fn buy(c:&mut TokenMarket,buyer:&str,id:&str,amount:u128)->U128{ctx("test-usd.testnet",0,vec![]);c.ft_on_transfer(a(buyer),U128(amount),near_sdk::serde_json::to_string(&PurchaseMsg{feature:feature(),order_id:id.into()}).unwrap())}
fn reject(f:impl FnOnce()){assert!(catch_unwind(AssertUnwindSafe(f)).is_err());}
#[test]fn token_units_clip_at_cap_and_later_sales_are_merchant_only(){let mut c=setup();for (id,r,m)in[("one",1750,5250),("two",1250,5750),("three",0,7000)]{assert_eq!(buy(&mut c,"alice.testnet",id,7000).0,0);let o=c.get_order(a("alice.testnet"),id.into()).unwrap();assert_eq!((o.developer_share.0,o.merchant_share.0),(r,m));}assert_eq!((c.sales,c.claimable),(21000,21000));assert_eq!(c.get_sku(feature()).unwrap().paid.0,3000);assert_eq!(c.get_payout(a("merchant.testnet")).claimable.0,18000);}
#[test]fn rejected_purchase_returns_all_tokens_without_credit_or_allocation(){let mut c=setup();for (id,amount)in[("bad",6999),("bad",7001),("bad",0)]{assert_eq!(buy(&mut c,"alice.testnet",id,amount).0,amount);}assert_eq!(buy(&mut c,"alice.testnet","one",7000).0,0);assert_eq!(buy(&mut c,"alice.testnet","one",7000).0,7000);assert_eq!(c.sales,7000);assert_eq!(c.get_credits(a("alice.testnet"),feature()).0,1);ctx("test-usd.testnet",0,vec![]);assert_eq!(c.ft_on_transfer(a("alice.testnet"),U128(7000),"malformed".into()).0,7000);}
#[test]fn non_allowlisted_token_native_payment_and_unaccepted_terms_cannot_mint_access(){let mut c=setup();ctx("fake-usd.testnet",0,vec![]);reject(||{c.ft_on_transfer(a("alice.testnet"),U128(7000),"{}".into());});ctx("test-usd.testnet",1,vec![]);reject(||{c.ft_on_transfer(a("alice.testnet"),U128(7000),"{}".into());});c.skus.get_mut(&feature()).unwrap().accepted=false;assert_eq!(buy(&mut c,"alice.testnet","one",7000).0,7000);assert_eq!(c.sales,0);}
#[test]fn consumption_is_buyer_specific_and_replay_safe_even_after_pause(){let mut c=setup();buy(&mut c,"alice.testnet","one",7000);ctx("bob.testnet",0,vec![]);reject(||{c.consume_use(feature(),"action".into());});ctx("merchant.testnet",0,vec![]);c.set_paused(feature(),true);assert_eq!(buy(&mut c,"alice.testnet","two",7000).0,7000);ctx("alice.testnet",0,vec![]);assert_eq!(c.consume_use(feature(),"action".into()).0,0);reject(||{c.consume_use(feature(),"action".into());});assert_eq!(c.get_action(a("alice.testnet"),"action".into()),Some(feature()));}
#[test]fn failed_token_payout_restores_only_owner_and_pending_nonce_blocks_reentrancy(){let mut c=setup();buy(&mut c,"alice.testnet","one",7000);ctx("merchant.testnet",1,vec![]);c.withdraw_tokens(U128(5250));reject(||{c.withdraw_tokens(U128(1));});ctx("stranger.testnet",0,vec![PromiseResult::Successful(vec![])]);reject(||{c.on_withdraw(a("merchant.testnet"),U64(1));});ctx("token-market.testnet",0,vec![PromiseResult::Failed]);assert!(!c.on_withdraw(a("merchant.testnet"),U64(1)));assert_eq!(c.get_payout(a("dev.testnet")).claimable.0,1750);ctx("merchant.testnet",1,vec![]);c.withdraw_tokens(U128(5250));ctx("token-market.testnet",0,vec![PromiseResult::Successful(vec![])]);reject(||{c.on_withdraw(a("merchant.testnet"),U64(1));});assert!(c.on_withdraw(a("merchant.testnet"),U64(2)));assert_eq!(c.sales,c.claimable+c.pending+c.withdrawn);reject(||{c.on_withdraw(a("merchant.testnet"),U64(2));});}
#[test]fn uncertain_token_return_is_not_treated_as_failed_transfer(){let mut c=setup();buy(&mut c,"alice.testnet","one",7000);ctx("dev.testnet",1,vec![]);c.withdraw_tokens(U128(1750));ctx("token-market.testnet",0,vec![PromiseResult::Successful(vec![0;64])]);reject(||{c.on_withdraw(a("dev.testnet"),U64(1));});assert_eq!(c.pending,1750);assert_eq!(c.get_payout(a("dev.testnet")).claimable.0,0);}
#[test]fn merchant_funds_order_and_action_storage_no_unfunded_growth(){let mut c=setup();c.skus.get_mut(&feature()).unwrap().storage_available=U128(0);assert_eq!(buy(&mut c,"alice.testnet","one",7000).0,7000);assert_eq!(c.sales,0);assert_eq!(c.get_credits(a("alice.testnet"),feature()).0,0);}
#[test]fn domain_separated_token_terms_require_developer_acceptance_and_exact_digest(){let mut c=setup();let f=c.get_sku(feature()).unwrap();assert_ne!(f.terms_hash,f.source_terms_hash);ctx("stranger.testnet",0,vec![]);reject(||{c.accept_token_terms(feature(),f.terms_hash.clone());});assert_eq!(split(u128::MAX,10000),u128::MAX);}
